1	import { useEffect, useState, type CSSProperties } from "react";
2	import {
3	  Breadcrumb,
4	  BreadcrumbItem,
5	  BreadcrumbList,
6	  BreadcrumbPage,
7	  BreadcrumbSeparator,
8	} from "./Breadcrumb";
9	import { KeptFloating } from "./onboarding/KeptFloating";
10	import { MemoryMatch } from "./onboarding/MemoryMatch";
11	import { OnboardingMascot } from "./onboarding/OnboardingMascot";
12	import { preloadOnboardingPhotos } from "./onboarding/onboardingMedia";
13	import { ReadsPictures } from "./onboarding/ReadsPictures";
14	import { SplitText } from "./onboarding/SplitText";
15	
16	const STAGE_WIDTH = 960;
17	const STAGE_HEIGHT = 540;
18	const LAST_SCREEN = 4;
19	/**
20	 * Drawn size of the big cropped mascot at stage scale 1; the body is about 63% of it.
21	 * Its centre sits 0.2 of this from the window's side and bottom edges. The body
22	 * never shrinks below 0.237 of it, so the blob keeps bleeding off both edges
23	 * however it breathes and turns.
24	 */
25	const MASCOT_SIZE = 860;
26	/** Eyes stay turned toward each screen's text (yaw + is right, pitch + is up). */
27	const WELCOME_LOOK = { yaw: -15, pitch: 24 };
28	const FAREWELL_LOOK = { yaw: 30, pitch: 12 };
29	
30	const welcomeFaces = ["neutre", "curieux", "heureux", "attentif"] as const;
31	const farewellFaces = ["heureux", "neutre", "fier", "timide"] as const;
32	
33	function fitScale() {
34	  return Math.min(1, window.innerWidth / STAGE_WIDTH, window.innerHeight / STAGE_HEIGHT);
35	}
36	
37	export function FirstRunOverlay({ onFinish }: { onFinish: () => void }) {
38	  const [screen, setScreen] = useState(0);
39	  const [scale, setScale] = useState(fitScale);
40	
41	  useEffect(() => {
42	    const update = () => setScale(fitScale());
43	    const onKeyDown = (event: KeyboardEvent) => {
44	      if (event.key === "Escape") onFinish();
45	    };
46	    window.addEventListener("resize", update);
47	    window.addEventListener("keydown", onKeyDown);
48	    return () => {
49	      window.removeEventListener("resize", update);
50	      window.removeEventListener("keydown", onKeyDown);
51	    };
52	  }, [onFinish]);
53	
54	  // First launch keeps the window hidden until this screen has painted, and
55	  // the later screens' photos decode meanwhile so none of them pop in.
56	  useEffect(() => {
57	    preloadOnboardingPhotos();
58	    let frame = requestAnimationFrame(() => {
59	      frame = requestAnimationFrame(
60	        () => void window.inkling?.windowControls.ready().catch(() => null),
61	      );
62	    });
63	    return () => cancelAnimationFrame(frame);
64	  }, []);
65	
66	  const advance = () => (screen === LAST_SCREEN ? onFinish() : setScreen(screen + 1));
67	
68	  const actions = (style: CSSProperties) => (
69	    <div className="first-run-actions" style={style}>
70	      <button type="button" className="first-run-primary" onClick={advance}>
71	        {screen === LAST_SCREEN ? "Open my library" : "Continue"}
72	      </button>
73	      {screen > 0 ? (
74	        <button type="button" className="first-run-quiet" onClick={() => setScreen(screen - 1)}>
75	          Back
76	        </button>
77	      ) : null}
78	      <button type="button" className="first-run-quiet" onClick={onFinish}>
79	        Skip
80	      </button>
81	    </div>
82	  );
83	
84	  const mascotSize = MASCOT_SIZE * scale;
85	
86	  return (
87	    <div
88	      className="first-run-overlay"
89	      role="dialog"
90	      aria-modal="true"
91	      aria-label="Welcome to inkling"
92	    >
93	      {/* The big mascot hangs off the window's corner, not the stage's, so it
94	          stays cropped by the window edge at any size. */}
95	      {screen === 0 ? (
96	        <OnboardingMascot
97	          key="welcome"
98	          size={mascotSize}
99	          faces={welcomeFaces}
100	          look={WELCOME_LOOK}
101	          style={{ right: -0.3 * mascotSize, bottom: -0.3 * mascotSize }}
102	        />
103	      ) : null}
104	      {screen === LAST_SCREEN ? (
105	        <OnboardingMascot
106	          key="farewell"
107	          size={mascotSize}
108	          faces={farewellFaces}
109	          look={FAREWELL_LOOK}
110	          style={{ left: -0.3 * mascotSize, bottom: -0.3 * mascotSize }}
111	        />
112	      ) : null}
113	
114	      <div
115	        key={screen}
116	        className="first-run-stage"
117	        style={{ transform: `translate(-50%, -50%) scale(${scale})` }}
118	      >
119	        {screen === 0 ? (
120	          <>
121	            <SplitText
122	              text="Drop something in."
123	              className="first-run-headline"
124	              style={{ left: 72, top: 156 }}
125	            />
126	            <p className="first-run-body" style={{ left: 72, top: 221 }}>
127	              Paste a link, drop in a file, or grab a screenshot.
128	              <br />
129	              It&apos;s kept the moment it lands. No folders to pick.
130	            </p>
131	            <div className="first-run-keys" style={{ left: 72, top: 291 }}>
132	              <kbd>Ctrl</kbd>
133	              <kbd>V</kbd>
134	              <span>works anywhere in inkling</span>
135	            </div>
136	            {actions({ left: 72, top: 348 })}
137	          </>
138	        ) : null}
139	
140	        {screen === 1 ? (
141	          <>
142	            <KeptFloating />
143	            <SplitText
144	              text="Kept as it came."
145	              className="first-run-headline is-centered"
146	              style={{ top: 164 }}
147	            />
148	            <p className="first-run-body is-centered" style={{ top: 232 }}>
149	              Articles, photos, PDFs, quotes, notes and posts each get
150	              <br />
151	              their own card, right away. Reading and indexing happen
152	              <br />
153	              quietly while you keep going.
154	            </p>
155	            {actions({ top: 337, left: 0, right: 0, justifyContent: "center" })}
156	          </>
157	        ) : null}
158	
159	        {screen === 2 ? (
160	          <>
161	            <MemoryMatch />
162	            <SplitText
163	              text="Half a memory is enough."
164	              className="first-run-headline is-centered"
165	              style={{ top: 312 }}
166	              delay={0.4}
167	            />
168	            <p className="first-run-body is-centered" style={{ top: 376 }}>
169	              Describe it the way it comes back to you. Search runs on this
170	              <br />
171	              computer, so nothing you save leaves it.
172	            </p>
173	            {actions({ top: 449, left: 0, right: 0, justifyContent: "center" })}
174	          </>
175	        ) : null}
176	
177	        {screen === 3 ? (
178	          <>
179	            <ReadsPictures />
180	            <SplitText
181	              text="It reads your pictures, too."
182	              className="first-run-headline is-wrapped"
183	              style={{ left: 72, top: 92, width: 390 }}
184	              delay={0.45}
185	            />
186	            <p className="first-run-body" style={{ left: 72, top: 230 }}>
187	              Words inside screenshots, photos and PDFs are
188	              <br />
189	              searchable. Remember one word, find the whole
190	              <br />
191	              thing. All on this computer.
192	            </p>
193	            <div className="first-run-keys" style={{ left: 72, top: 336 }}>
194	              <kbd>Ctrl</kbd>
195	              <kbd>K</kbd>
196	              <span>to search from anywhere</span>
197	            </div>
198	            {actions({ left: 72, top: 386 })}
199	          </>
200	        ) : null}
201	
202	        {screen === LAST_SCREEN ? (
203	          <>
204	            <SplitText
205	              text="It's all yours."
206	              className="first-run-headline"
207	              style={{ left: 500, top: 145 }}
208	            />
209	            <p className="first-run-body" style={{ left: 500, top: 214 }}>
210	              Your library lives on this computer, not in an
211	              <br />
212	              account. Export a full copy whenever you like.
213	              <br />
214	              inkling only goes online to fetch the links you save.
215	            </p>
216	            <Breadcrumb className="first-run-crumb" style={{ left: 500, top: 305 }}>
217	              <BreadcrumbList>
218	                <BreadcrumbItem>Settings</BreadcrumbItem>
219	                <BreadcrumbSeparator />
220	                <BreadcrumbItem>Data</BreadcrumbItem>
221	                <BreadcrumbSeparator />
222	                <BreadcrumbItem>
223	                  <BreadcrumbPage>Export a copy</BreadcrumbPage>
224	                </BreadcrumbItem>
225	              </BreadcrumbList>
226	            </Breadcrumb>
227	            {actions({ left: 500, top: 356 })}
228	          </>
229	        ) : null}
230	      </div>
231	    </div>
232	  );
233	}
