1	import { useEffect, useState, type CSSProperties } from "react";
2	import { InklingMascot } from "../mascot/InklingMascot";
3	import { prefersReducedMotion } from "../mascot/mascotStore";
4	
5	/** How long each face holds before the next one glides in. */
6	const FACE_HOLD_MS = 3400;
7	
8	/**
9	 * The large, cropped mascot on the first and last welcome screens. It drifts
10	 * and blinks like the sidebar one, and wanders through a few calm faces. It
11	 * owns its own engine, so the library's mascot keeps its clock and its face.
12	 */
13	export function OnboardingMascot({
14	  size,
15	  faces,
16	  look,
17	  style,
18	}: {
19	  size: number;
20	  faces: readonly string[];
21	  /** Where the eyes stay pointed (toward the screen's text) through every face. */
22	  look: { yaw: number; pitch: number };
23	  style?: CSSProperties;
24	}) {
25	  const [reduced] = useState(prefersReducedMotion);
26	  const [faceIndex, setFaceIndex] = useState(0);
27	
28	  useEffect(() => {
29	    if (reduced || faces.length < 2) return;
30	    const timer = window.setInterval(
31	      () => setFaceIndex((index) => (index + 1) % faces.length),
32	      FACE_HOLD_MS,
33	    );
34	    return () => window.clearInterval(timer);
35	  }, [faces, reduced]);
36	
37	  return (
38	    <div className="first-run-mascot" style={style} aria-hidden="true">
39	      <InklingMascot
40	        size={size}
41	        state="inkling-drift-faced"
42	        expression={faces[faceIndex]}
43	        ink="#2b2623"
44	        paper="#e5ddd2"
45	        playing={!reduced}
46	        look={look}
47	      />
48	    </div>
49	  );
50	}
