1	import { useEffect, useRef, useState } from "react";
2	import { BotEngine, type BotFrame } from "./bot/engine";
3	import { EXPRESSION_BY_ID, DEFAULT_EXPRESSION } from "./bot/expressions";
4	import { COLOR_BY_ID, SHAPE_BY_ID, DEFAULT_SHAPE } from "./bot/skins";
5	import { RAYON } from "./bot/repere";
6	import { STATE_BY_ID, type StateId } from "./bot/states";
7	import { MascotFigure } from "./MascotFigure";
8	
9	export type { StateId };
10	
11	export interface InklingMascotProps {
12	  size?: number;
13	  shape?: string;
14	  color?: string;
15	  /** Body color as any CSS color, overriding `color` when a skin hex will not do. */
16	  ink?: string;
17	  expression?: string;
18	  paper?: string;
19	  /** Freeze on one exact frame (seconds into the state). No animation loop. */
20	  frozenAt?: number;
21	  state?: StateId;
22	  /** Play the state live (breathing, blinking, gaze drift). Ignored when frozenAt is set. */
23	  playing?: boolean;
24	  /**
25	   * Hold the head turned toward a fixed direction, in degrees (positive yaw =
26	   * right, positive pitch = up). It replaces the gaze of every expression, so
27	   * the face can change mood while the eyes keep looking at the same spot. A
28	   * little drift stays, so the eyes still feel alive.
29	   */
30	  look?: { yaw: number; pitch: number };
31	}
32	
33	const HELD_LOOK_WANDER = 0.35;
34	
35	const heldLook = (look: { yaw: number; pitch: number }) => ({
36	  ...look,
37	  mix: 1,
38	  spin: 0,
39	  wander: HELD_LOOK_WANDER,
40	});
41	
42	/**
43	 * Self-contained mascot: owns its engine and animation loop. Used by the
44	 * dev board (?mascot) and frozen-frame renders. The live app slots share one
45	 * engine through mascotStore instead, so the mascot can move between slots
46	 * without resetting its clock.
47	 */
48	export function InklingMascot({
49	  size = 80,
50	  shape = "inkling-splash",
51	  color = "inkling",
52	  ink: inkOverride,
53	  expression = DEFAULT_EXPRESSION,
54	  paper = "#faf9f6",
55	  frozenAt,
56	  state = "idle",
57	  playing = true,
58	  look,
59	}: InklingMascotProps) {
60	  const shapeRadii = SHAPE_BY_ID.get(shape)?.radii ?? SHAPE_BY_ID.get(DEFAULT_SHAPE)?.radii ?? null;
61	  const ink = inkOverride ?? COLOR_BY_ID.get(color)?.hex ?? "#1a1a1a";
62	  const expr = EXPRESSION_BY_ID.get(expression) ?? null;
63	
64	  const [engine] = useState(() => {
65	    const created = new BotEngine(RAYON, state, shapeRadii, expr);
66	    // Dated before the clock starts so the very first frame already looks there.
67	    if (look) created.setLook(heldLook(look), -10);
68	    return created;
69	  });
70	  const [frame, setFrame] = useState<BotFrame>(() => engine.sample(frozenAt ?? 0));
71	  // Running clock, shared with the transition setters below. Dating a change
72	  // at a stale time (e.g. always 0) completes its morph instantly and reads
73	  // as a hard cut — this ref is what keeps shape/state/expression gliding.
74	  const clockRef = useRef(0);
75	
76	  useEffect(() => {
77	    engine.setShape(shapeRadii, clockRef.current);
78	    engine.setExpression(expr, clockRef.current);
79	    if (frozenAt !== undefined) setFrame(engine.sample(frozenAt));
80	  }, [engine, shapeRadii, expr, frozenAt]);
81	
82	  const lookYaw = look?.yaw;
83	  const lookPitch = look?.pitch;
84	  useEffect(() => {
85	    if (lookYaw === undefined || lookPitch === undefined) engine.setLook(null, clockRef.current);
86	    else engine.setLook(heldLook({ yaw: lookYaw, pitch: lookPitch }), clockRef.current);
87	  }, [engine, lookYaw, lookPitch]);
88	
89	  useEffect(() => {
90	    if (engine.state !== state) engine.setState(state, clockRef.current);
91	    if (frozenAt !== undefined) setFrame(engine.sample(frozenAt));
92	  }, [engine, state, frozenAt]);
93	
94	  useEffect(() => {
95	    if (frozenAt !== undefined || !playing) return;
96	    let raf = 0;
97	    let last = 0;
98	    let clock = 0;
99	    const tick = (ms: number) => {
100	      raf = requestAnimationFrame(tick);
101	      const dt = last ? Math.min((ms - last) / 1000, 0.064) : 0;
102	      last = ms;
103	      clock += dt;
104	      clockRef.current = clock;
105	      setFrame(engine.sample(clock));
106	    };
107	    raf = requestAnimationFrame(tick);
108	    return () => cancelAnimationFrame(raf);
109	  }, [engine, frozenAt, playing]);
110	
111	  return <MascotFigure frame={frame} size={size} ink={ink} paper={paper} />;
112	}
113	
114	export function isKnownMascotState(value: string): value is StateId {
115	  return STATE_BY_ID.has(value as StateId);
116	}
