1	// biome-ignore-all lint/suspicious/noArrayIndexKey: every mapped array here is fixed geometry derived from a profile, and never reorders.
2	import { useId } from "react";
3	import { DEMI_VIEWBOX, RAYON } from "./bot/repere";
4	import { mixHex } from "./bot/skins";
5	import type { BotFrame } from "./bot/engine";
6	
7	export interface MascotFigureProps {
8	  frame: BotFrame;
9	  size: number;
10	  ink?: string;
11	  /** Eye color. Transparent keeps the old logo's see-through eyes on any theme. */
12	  paper?: string;
13	  className?: string;
14	}
15	/**
16	 * Pure SVG renderer for a sampled bot frame. Same recipe as bloub's
17	 * BloubBot.vue: eyes are holes cut in a <mask> (never white shapes on top),
18	 * backed by a paper-colored path so decor drawn behind the body cannot show
19	 * through the eyes.
20	 */
21	export function MascotFigure({
22	  frame,
23	  size,
24	  ink = "#1a1a1a",
25	  paper = "#faf9f6",
26	  className,
27	}: MascotFigureProps) {
28	  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
29	  const maskId = `inkling-mask-${uid}`;
30	  const VB = DEMI_VIEWBOX;
31	
32	  const dotFill = (dot: BotFrame["dots"][number]) => {
33	    if (dot.color) return dot.color;
34	    return dot.depth === undefined
35	      ? ink
36	      : mixHex(paper === "transparent" ? ink : paper, ink, dot.depth);
37	  };
38	
39	  return (
40	    <svg
41	      width={size}
42	      height={size}
43	      viewBox={`${-VB} ${-VB} ${VB * 2} ${VB * 2}`}
44	      role="img"
45	      aria-label="inkling mascot"
46	      className={className}
47	    >
48	      <defs>
49	        <mask id={maskId} maskUnits="userSpaceOnUse" x={-VB} y={-VB} width={VB * 2} height={VB * 2}>
50	          <path d={frame.bodyPath} fill="#fff" />
51	          {frame.eyes.map((eye, i) => (
52	            <path key={i} d={eye.d} transform={eye.matrix} opacity={eye.alpha} fill="#000" />
53	          ))}
54	          {frame.notch && (
55	            <circle cx={frame.notch.x} cy={frame.notch.y} r={frame.notch.r} fill="#000" />
56	          )}
57	        </mask>
58	        {frame.arcs.map((arc) => (
59	          <linearGradient
60	            key={arc.id}
61	            id={`${uid}-${arc.id}`}
62	            gradientUnits="userSpaceOnUse"
63	            x1={arc.grad.x1}
64	            y1={arc.grad.y1}
65	            x2={arc.grad.x2}
66	            y2={arc.grad.y2}
67	          >
68	            {arc.grad.stops.map((c, i) => (
69	              <stop key={i} offset={i / (arc.grad.stops.length - 1)} stopColor={c} />
70	            ))}
71	          </linearGradient>
72	        ))}
73	      </defs>
74	
75	      <g fill="none" strokeLinecap="round">
76	        {frame.arcs.map((arc) => (
77	          <path
78	            key={`b${arc.id}`}
79	            d={arc.back}
80	            stroke={`url(#${uid}-${arc.id})`}
81	            strokeWidth={arc.width}
82	            opacity={arc.opacity}
83	          />
84	        ))}
85	      </g>
86	
87	      {frame.dotsBehind && (
88	        <g>
89	          {frame.dots.map((dot, i) =>
90	            dot.d ? (
91	              <path
92	                key={`pb${i}`}
93	                d={dot.d}
94	                transform={`translate(${dot.x} ${dot.y}) rotate(${dot.rot ?? 0}) scale(${RAYON})`}
95	                fill={dotFill(dot)}
96	                opacity={dot.opacity}
97	              />
98	            ) : (
99	              <circle
100	                key={`pb${i}`}
101	                cx={dot.x}
102	                cy={dot.y}
103	                r={dot.r}
104	                fill={dotFill(dot)}
105	                opacity={dot.opacity}
106	              />
107	            ),
108	          )}
109	        </g>
110	      )}
111	
112	      <g opacity={frame.bodyAlpha}>
113	        <path d={frame.bodyPath} fill={paper} />
114	        <g mask={`url(#${maskId})`}>
115	          <rect x={-VB} y={-VB} width={VB * 2} height={VB * 2} fill={ink} />
116	        </g>
117	      </g>
118	
119	      {!frame.dotsBehind && (
120	        <g>
121	          {frame.dots.map((dot, i) =>
122	            dot.d ? (
123	              <path
124	                key={`pf${i}`}
125	                d={dot.d}
126	                transform={`translate(${dot.x} ${dot.y}) rotate(${dot.rot ?? 0}) scale(${RAYON})`}
127	                fill={dotFill(dot)}
128	                opacity={dot.opacity}
129	              />
130	            ) : (
131	              <circle
132	                key={`pf${i}`}
133	                cx={dot.x}
134	                cy={dot.y}
135	                r={dot.r}
136	                fill={dotFill(dot)}
137	                opacity={dot.opacity}
138	              />
139	            ),
140	          )}
141	        </g>
142	      )}
143	
144	      {frame.notif && (
145	        <circle cx={frame.notif.x} cy={frame.notif.y} r={frame.notif.r} fill="#3b93f0" />
146	      )}
147	
148	      <g fill="none" strokeLinecap="round">
149	        {frame.arcs.map((arc) => (
150	          <path
151	            key={`f${arc.id}`}
152	            d={arc.front}
153	            stroke={`url(#${uid}-${arc.id})`}
154	            strokeWidth={arc.width}
155	            opacity={arc.opacity}
156	          />
157	        ))}
158	      </g>
159	    </svg>
160	  );
161	}
162	
163	/**
164	 * Eyes only, custom fit for the search field.
165	 * The generic MascotEyes uses a tall crop (-60 -80 150 135) that reserves
166	 * room for the full motion range across all states. In a 50px search bar
167	 * that empty space reads as a vertical offset, eyes pinned high with dead
168	 * space below. This uses a tight crop around the drift + attentif/curieux
169	 * eye centroid (about 25, -50) so the gaze sits optically centered.
170	 */
171	const SEARCH_EYES_VIEWBOX = "-14 -88 78 80";
172	
173	export function MascotSearchEyes({
174	  frame,
175	  size,
176	  ink = "var(--library-text)",
177	  className,
178	}: {
179	  frame: BotFrame;
180	  size: number;
181	  ink?: string;
182	  className?: string;
183	}) {
184	  return (
185	    <svg
186	      width={size}
187	      height={(size * 80) / 78}
188	      viewBox={SEARCH_EYES_VIEWBOX}
189	      preserveAspectRatio="xMidYMid meet"
190	      role="img"
191	      aria-label="inkling mascot eyes"
192	      className={className}
193	    >
194	      {frame.eyes.map((eye, i) => (
195	        <path key={i} d={eye.d} transform={eye.matrix} opacity={eye.alpha} fill={ink} />
196	      ))}
197	    </svg>
198	  );
199	}
