122	/**
123	 * Moteur sans horloge : `sample(t)` est une fonction pure du temps.
124	 *
125	 * Consequence pratique : pause, reprise, ralenti et saut a une date arbitraire
126	 * donnent exactement la meme image, et le rendu est testable sans DOM.
127	 */
128	export class BotEngine {
129	  /** rayon de la boule au repos, en unites de viewBox */
130	  readonly scale: number;
131	
132	  private cur: StateId;
133	  private prev: StateId | null = null;
134	  /**
135	   * Pose de depart FIGEE, posee seulement quand un changement d'etat arrive alors qu'un
136	   * fondu est deja en cours. Cf. `setState`.
137	   */
138	  private departFige: Pose | null = null;
139	  private tCur = 0;
140	  private tPrev = 0;
141	  private blinkAt = -10;
142	  private pts: Point[] = [];
143	  private shape: number[] | null = null;
144	  private shapePrev: number[] | null = null;
145	  private shapeAt = -10;
146	  private expr: BotExpression | null = null;
147	  private exprPrev: BotExpression | null = null;
148	  private exprAt = -10;
149	  private look: Look = NO_LOOK;
150	  private lookPrev: Look = NO_LOOK;
151	  private lookAt = -10;
152	  /** duree de rattrapage en cours ; voir `LOOK_MORPH`, sa valeur par defaut */
153	  private lookMorph = 0.24;
154	
155	  /** duree du morph quand on change la forme du corps */
156	  static readonly SHAPE_MORPH = 0.45;
157	
158	  /**
159	   * Duree de rattrapage du regard vers la cible. Plus court que `SHAPE_MORPH` :
160	   * un regard qui suit doit paraitre attentif, pas visqueux. Comme la cible est
161	   * reposee a chaque mouvement de souris, c'est cette duree qui donne au suivi
162	   * son inertie — le regard n'atteint jamais tout a fait un curseur qui bouge.
163	   */
164	  static readonly LOOK_MORPH = 0.24;
165	
166	  constructor(
167	    scale = 100,
168	    initial: StateId = "idle",
169	    shape: number[] | null = null,
170	    expression: BotExpression | null = null,
171	  ) {
172	    this.scale = scale;
173	    this.cur = initial;
174	    this.shape = shape;
175	    this.expr = expression;
176	  }
177	
178	  /**
179	   * Expression de repos choisie dans le personnalisateur. Comme la forme, elle
180	   * glisse vers la nouvelle valeur au lieu de sauter.
181	   */
182	  setExpression(expression: BotExpression | null, now = 0) {
183	    if (expression === this.expr) return;
184	    this.exprPrev = this.expr;
185	    this.expr = expression;
186	    this.exprAt = now;
187	  }
188	
189	  /** Expression effective a l'instant `now`, morph en cours compris. */
190	  private exprAtTime(now: number): BotExpression | null {
191	    const to = this.expr;
192	    const from = this.exprPrev;
193	    if (!to || !from) return to;
194	    const k = (now - this.exprAt) / BotEngine.SHAPE_MORPH;
195	    if (k >= 1) return to;
196	    return blendExpression(from, to, easings.easeOutQuint(clamp(k)));
197	  }
198	
199	  /**
200	   * Forme choisie dans le personnalisateur. Elle ne remplace le corps que sur
201	   * les etats au repos (`baseBody`) : sur les autres, la silhouette EST
202	   * l'animation et ne doit pas etre ecrasee.
203	   *
204	   * Le changement se fait en morph, pas d'un coup : comme toutes les formes sont
205	   * echantillonnees aux memes angles, il suffit d'interpoler les rayons.
206	   */
207	  setShape(radii: number[] | null, now = 0) {
208	    if (radii === this.shape) return;
209	    this.shapePrev = this.shape;
210	    this.shape = radii;
211	    this.shapeAt = now;
212	  }
213	
214	  /**
215	   * Forme effective a l'instant `now`, morph en cours compris.
216	   *
217	   * Ne remet PAS `shapePrev` a null en fin de morph : `sample` doit rester une
218	   * fonction pure du temps, donc relire une date passee doit redonner l'image
219	   * intermediaire. On garde juste une reference de plus.
220	   */
221	  private shapeAtTime(now: number): number[] | null {
222	    const to = this.shape;
223	    const from = this.shapePrev;
224	    if (!to || !from) return to;
225	    const k = (now - this.shapeAt) / BotEngine.SHAPE_MORPH;
226	    if (k >= 1) return to;
227	    const t = easings.easeOutQuint(clamp(k));
228	    // alloue seulement pendant le morph ; hors morph on rend le tableau tel quel
229	    return to.map((r, i) => lerp(from[i] ?? r, r, t));
230	  }
231	
232	  /**
233	   * Nouvelle cible de regard, `null` pour revenir a celui de l'etat.
234	   *
235	   * Elle repart de la valeur COURANTE, et non de la cible precedente comme
236	   * `setShape` : cette methode est appelee a chaque mouvement de pointeur, et
237	   * repartir de l'ancienne cible ferait reculer le regard d'un cran avant
238	   * chaque rattrapage — le suivi tremblerait au lieu de glisser.
239	   *
240	   * Meme contrat que `setShape` par ailleurs : l'etat externe entre par un
241	   * setter horodate, jamais par une variable lue pendant `sample`, sinon le
242	   * moteur cesse d'etre une fonction pure du temps.
243	   */
244	  setLook(look: Look | null, now: number, morph = BotEngine.LOOK_MORPH) {
245	    /*
246	     * Une cible non finie est refusee. Le moteur GARDE la derniere : un `NaN`
247	     * pose une seule fois se propagerait a chaque image et le bot ne se
248	     * reposerait plus jamais. C'est arrive pour de vrai — un
249	     * `getBoundingClientRect` sur une boite de taille nulle donne `0 / 0` chez
250	     * l'appelant. Celui-la est corrige, mais le moteur n'a pas a dependre de la
251	     * prudence de ses appelants pour rester rejouable.
252	     */
253	    if (look && !Number.isFinite(look.yaw + look.pitch + look.mix + look.spin + look.wander)) {
254	      return;
255	    }
256	    this.lookPrev = this.lookAtTime(now);
257	    this.look = look ?? NO_LOOK;
258	    this.lookAt = now;
259	    this.lookMorph = morph;
260	  }
261	
262	  /** Regard effectif a l'instant `now`, rattrapage en cours compris. */
263	  private lookAtTime(now: number): Look {
264	    const k = (now - this.lookAt) / this.lookMorph;
265	    if (k >= 1) return this.look;
266	    return lerpLook(this.lookPrev, this.look, easings.easeOutQuint(clamp(k)));
267	  }
268	
269	  private posed(
270	    def: StateDef,
271	    t: number,
272	    shape: number[] | null,
273	    expr: BotExpression | null,
274	  ): Pose {
275	    let pose = def.pose(t);
276	    if (def.baseBody && shape) {
277	      // on garde la pose (rotation, decalage, squash) et on n'echange que le profil
278	      pose = { ...pose, sil: { ...pose.sil, radii: shape } };
279	    }
280	    if (def.baseFace && expr) {
281	      pose = { ...pose, gaze: expr.gaze, split: expr.split, eyes: expr.eyes };
282	    }
283	    return pose;
284	  }
285	
286	  /**
287	   * Decalage des yeux a l'instant `now` pour un etat donne, en unites de rayon de boule.
288	   *
289	   * Il est LU dans une table et interpole, jamais recalcule : `eyefit.ts` explique
290	   * pourquoi cette distinction est tout le correctif. Ici il ne reste qu'a l'interpoler
291	   * sur l'axe de la forme, avec exactement la courbe et la duree du morph de silhouette
292	   * — c'est la meme cause, donc ce doit etre le meme mouvement.
293	   *
294	   * On interroge la table sur les BORNES du morph (`shapePrev` et `shape`) et non sur le
295	   * profil que rend `shapeAtTime` : celui-la est un tableau neuf alloue a chaque image,
296	   * donc sans identite, et il n'existe dans aucune table.
297	   */
298	  private decalageAtTime(now: number, state: StateId): { x: number; y: number } {
299	    /**
300	     * Un axe de morph : on lit la table sur ses deux BORNES et on interpole avec sa
301	     * courbe. Jamais sur la valeur interpolee — celle-la n'a pas d'identite et n'existe
302	     * dans aucune table, et c'est en la lui donnant a manger que les versions
303	     * precedentes tremblaient.
304	     */
305	    const surAxe = (
306	      debut: number,
307	      duree: number,
308	      a: { x: number; y: number },
309	      b: { x: number; y: number },
310	    ) => {
311	      if (a === b) return b;
312	      const k = (now - debut) / duree;
313	      if (k >= 1) return b;
314	      const t = easings.easeOutQuint(clamp(k));
315	      return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t) };
316	    };
317	
318	    // axe de l'expression, pour chacune des deux formes en presence
319	    const parForme = (radii: number[] | null) =>
320	      surAxe(
321	        this.exprAt,
322	        BotEngine.SHAPE_MORPH,
323	        decalageDesYeux(radii, state, this.exprPrev?.id ?? null),
324	        decalageDesYeux(radii, state, this.expr?.id ?? null),
325	      );
326	
327	    // puis axe de la forme
328	    return surAxe(
329	      this.shapeAt,
330	      BotEngine.SHAPE_MORPH,
331	      parForme(this.shapePrev),
332	      parForme(this.shape),
333	    );
334	  }
335	
336	  get state(): StateId {
337	    return this.cur;
338	  }
339	
340	  /**
341	   * Repart sur `id` SANS etat precedent, comme un moteur neuf pose sur cet etat.
342	   *
343	   * C'est ce que veut dire « rembobiner » pour ce moteur. `setState` seul ne peut pas le
344	   * faire : il garde l'etat quitte pour le fondre, ce qui est exactement son role en
345	   * lecture, et exactement ce qu'il ne faut pas quand on revient au debut d'une sequence.
346	   * Rejouer l'image 0 apres une passe complete melangeait le premier etat avec le DERNIER,
347	   * et l'export GIF s'ouvrait sur une boule sans yeux — la comete a un `eyeAlpha` nul.
348	   *
349	   * `sample` reste une fonction pure du temps : comme `setState`, ceci est un setter DATE,
350	   * appele par le pilote de la sequence, jamais pendant un echantillonnage.
351	   */
352	  reset(id: StateId, now: number) {
353	    this.cur = id;
354	    this.prev = null;
355	    this.departFige = null;
356	    this.tCur = now;
357	    this.tPrev = now;
358	    this.blinkAt = -10;
359	  }
360	
361	  /**
362	   * Origine du fondu en cours : la pose figee s'il y en a une, sinon l'etat quitte evalue
363	   * a son propre temps ecoule — donc encore en train de s'animer, ce qui est voulu.
364	   */
365	  private origine(now: number, shape: number[] | null, expr: BotExpression | null): Pose | null {
366	    if (this.departFige) return this.departFige;
367	    if (!this.prev) return null;
368	    const prevDef = STATE_BY_ID.get(this.prev)!;
369	    return this.posed(prevDef, Math.max(0, now - this.tPrev), shape, expr);
370	  }
371	
372	  /**
373	   * Pose composite a l'instant `now`, fondu en cours compris : exactement ce que `sample`
374	   * melange, avant la couche de vie au repos et de regard. Extraite pour que `setState`
375	   * puisse la figer.
376	   */
377	  private poseComposee(now: number): Pose {
378	    const def = STATE_BY_ID.get(this.cur)!;
379	    const shape = this.shapeAtTime(now);
380	    const expr = this.exprAtTime(now);
381	    const pose = this.posed(def, Math.max(0, now - this.tCur), shape, expr);
382	    const since = now - this.tCur;
383	    if (since >= def.morph) return pose;
384	    const origine = this.origine(now, shape, expr);
385	    if (!origine) return pose;
386	    return blendPose(origine, pose, easings.easeOutQuint(clamp(since / def.morph)));
387	  }
388	
389	  /**
390	   * Changement d'etat, date.
391	   *
392	   * Le moteur ne garde qu'UNE case d'historique, donc un changement qui arrive pendant un
393	   * fondu remplacait l'origine du melange par la pose PLEINE de l'etat qu'on quittait, au
394	   * lieu de l'image partiellement melangee qui etait a l'ecran. Mesure sur
395	   * `idle -> wide -> idle` a 100 ms : 35,9 px de saut contre 8,0 px de mouvement normal.
396	   *
397	   * On fige donc la pose composite courante et on melange depuis elle. Continu par
398	   * construction, quel que soit le nombre de changements enchaines.
399	   *
400	   * Et SEULEMENT dans ce cas. Figer a chaque changement arreterait net l'animation de
401	   * l'etat qu'on quitte pendant tout le fondu — le « ! » d'`alert` se figerait en pleine
402	   * course — alors qu'il n'y a rien a corriger hors morph : l'etat quitte y est deja
403	   * exactement l'image affichee. La lecture d'un montage, dont les blocs durent au moins
404	   * le plus long fondu (`MIN_BLOCK`), ne fige donc jamais rien et rend au bit ce qu'elle
405	   * rendait.
406	   */
407	  setState(id: StateId, now: number) {
408	    if (id === this.cur) return;
409	    const morph = STATE_BY_ID.get(this.cur)!.morph;
410	    const enPleinFondu = this.prev !== null && now - this.tCur < morph;
411	    this.departFige = enPleinFondu ? this.poseComposee(now) : null;
412	    this.prev = this.cur;
413	    this.tPrev = this.tCur;
414	    this.cur = id;
415	    this.tCur = now;
416	    // Dans la video, chaque changement de forme est masque par un clignement.
417	    if (STATE_BY_ID.get(id)?.blinkIn) this.blinkAt = now;
418	  }
419	
420	  sample(now: number): BotFrame {
421	    const R = this.scale;
422	    const def = STATE_BY_ID.get(this.cur)!;
423	    const shape = this.shapeAtTime(now);
424	    const expr = this.exprAtTime(now);
425	    let pose = this.posed(def, Math.max(0, now - this.tCur), shape, expr);
426	    let decalage = this.decalageAtTime(now, this.cur);
427	
428	    // --- transition -------------------------------------------------------
429	    const since = now - this.tCur;
430	    // L'etat precedent n'est jamais purge : `since < def.morph` suffit a
431	    // l'ignorer une fois le fondu passe, et l'oublier rendrait le moteur non
432	    // rejouable — relire une date d'avant la fin du fondu ne le retrouverait
433	    // plus. C'est l'optimisation qui parait innocente et qui casse tout.
434	    const origine = since < def.morph ? this.origine(now, shape, expr) : null;
435	    if (origine) {
436	      // Ease-out exponentiel : c'est la courbe mesuree sur la video. Le corps
437	      // n'a pas d'overshoot (seuls la pastille et l'ouverture des yeux en ont).
438	      // Le ratio est borne : relire une date ANTERIEURE au changement d'etat
439	      // donnerait un ratio negatif, que l'ease-out extrapole — la silhouette
440	      // part alors trente fois trop loin.
441	      const ratio = easings.easeOutQuint(clamp(since / def.morph));
442	      pose = blendPose(origine, pose, ratio);
443	      // Le decalage des yeux suit la MEME courbe que la silhouette qui le motive. Il vient
444	      // de l'etat quitte, que `setState` renseigne toujours en meme temps que l'origine —
445	      // le test est la pour le typage, pas pour un cas reel.
446	      const quitte = this.prev;
447	      if (quitte) {
448	        const avant = this.decalageAtTime(now, quitte);
449	        decalage = {
450	          x: lerp(avant.x, decalage.x, ratio),
451	          y: lerp(avant.y, decalage.y, ratio),
452	        };
453	      }
454	    }
455	
456	    // --- vie au repos -----------------------------------------------------
457	    const alive = pose.eyeAlpha > 0.01;
458	    const look = this.lookAtTime(now);
459	    const life = liveliness(now, { wander: alive ? look.wander : 0, blink: alive });
460	
461	    const gaze = {
462	      // Les deux visees REMPLACENT celles de la pose au lieu de s'y ajouter (voir
463	      // `Look`), et le tour se retranche en chemin. La derive s'ajoute APRES le
464	      // melange, sinon la cible l'annulerait en meme temps que la pose — or elle
465	      // doit survivre a une tete tournee sans pointeur.
466	      yaw: lerp(pose.gaze.yaw, look.yaw, look.mix) + life.dYaw - look.spin,
